sys_script_include.script:
var ExcelParser = Class.create();
ExcelParser.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	parseExcel: function() {
		gs.error('parseExcel');
		try {
			var attachmentId = this.getParameter('sysparm_id');
			if(!attachmentId) return JSON.stringify([]);
			gs.error('parseExcel:' + attachmentId);
			var gr = new GlideRecord('sys_attachment');
			gs.error('gr.get(attachmentId):' + gr.get(attachmentId));
			if(!gr.get(attachmentId)){
				gs.error('ERROR: cant find the file:');
				return "ERROR: cant find the file";
			}

			var attachment = new GlideSysAttachment();
			gs.error('parseExcel2.0:');
			var attachmentStream = attachment.getContentStream(attachmentId);

			gs.error('parseExcel2.1:'+ attachmentStream);
			var parser = new sn_impex.GlideExcelParser();
			parser.parse(attachmentStream);
			gs.error('parseExcel2.2:');

			var headers = parser.getColumnHeaders();
			gs.error('parseExcel2.3::' + headers);
			if(!headers || headers.length < 3) {
				return "ERROR: 3field need";
			}
			var result =[];
			while (parser.next()){
				var row = parser.getRow();
				result.push({
					'name': row[headers[0]] + '',
					'value': row[headers[1]] + '',
					'description': row[headers[2]] + ''
				});

			}
			return JSON.stringify(result);

		} catch (e) {
			return "ERROR: " + e.message;
		}

	},
    type: 'ExcelParser'
});
